import pandas as pd
from pyspark.sql import functions as F


@F.pandas_udf("string")
def volume_tag(volume: pd.Series) -> pd.Series:
    if volume is None:
        return "unknown"
    if volume >= 5_000_000:
        return "heavy"
    return "normal"


def solve(daily_prices):
    return daily_prices.select("symbol", "trade_date", "volume", volume_tag("volume").alias("tag"))
